function getPaloAltoNgfwTranslation(key, lang) {
    return (paloaltongfwTranslations[lang] && paloaltongfwTranslations[lang][key]) ||
           (paloaltongfwTranslations.en && paloaltongfwTranslations.en[key]) || null;
}

function applyPaloAltoNgfwTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.palo-alto-ngfw.") || key.startsWith("review.common."))) {
            const translation = getPaloAltoNgfwTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    console.log(`Applied ${count} palo-alto-ngfw translations`);
}

window.addEventListener("languageChanged", e => setTimeout(() => applyPaloAltoNgfwTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyPaloAltoNgfwTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyPaloAltoNgfwTranslations(window.i18n?.getCurrentLanguage() || "en");
}
